import {STORAGE_KEY,roles,dateKey,shiftDate,uid,clock,minutes,isDate,defaultState,emptyState,sanitizeState,validatePrefs,planDay,nextTask,applyTask} from './core.mjs';

const paths={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2m-8 3h2"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5"/>',circles:'<circle cx="8" cy="8" r="4"/><circle cx="16" cy="8" r="4"/><circle cx="8" cy="16" r="4"/><circle cx="16" cy="16" r="4"/>',sliders:'<path d="M4 21v-7m0-4V3m8 18v-9m0-4V3m8 18v-5m0-4V3M1 14h6m2-6h6m2 8h6"/>',sparkles:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3ZM20 2v4m-2-2h4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/>',shield:'<path d="M12 3 3 7v6c0 4 9 8 9 8s9-4 9-8V7l-9-4Z"/><path d="m8 12 3 3 5-6"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>','arrow-right':'<path d="M4 12h16m-6-6 6 6-6 6"/>','chevron-left':'<path d="m15 6-6 6 6 6"/>','chevron-right':'<path d="m9 6 6 6-6 6"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 4v16m8-16v16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>','check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12a21 21 0 0 0 18 0M12 10v4"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',leaf:'<path d="M20 3c-8 0-14 1-15 7s3 10 8 8 7-9 7-15ZM3 21l12-13"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 15a9 9 0 0 1-11-11 9 9 0 1 0 11 11Z"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 6a8 8 0 0 1 13 3M5 15a8 8 0 0 0 13 3"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14v6Z"/>',book:'<path d="M3 3h7a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3V3Zm18 0h-5a3 3 0 0 0-3 3v15a4 4 0 0 1 4-2h4V3Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',chevrons:'<path d="m5 4 7 8-7 8m7-16 7 8-7 8"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.sparkles}</svg>`;
const $=(s)=>document.querySelector(s);
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const roleOf=(id)=>roles.find(r=>r.id===id)||roles[0];
const tag=(id)=>{const r=roleOf(id);return `<span class="role-tag" style="--role-color:${r.color}">${r.short}</span>`;};
const roleIcon=(r)=>`<span class="role-icon" style="--role-color:${r.color}">${icon(r.icon)}</span>`;
const types={fact:'事实与进展',preference:'个人偏好',insight:'想法与心得'};
let state,storageError='',readBlocked=false,view=['today','memory','roles','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'today',taskFilter='all',memoryFilter='all',toastTimeout;
try{const raw=localStorage.getItem(STORAGE_KEY);state=raw?sanitizeState(JSON.parse(raw)):defaultState();}catch{state=emptyState();storageError='已有数据无法读取。为避免覆盖，当前修改暂不保存；可以到设置导出原始数据，再重置。';readBlocked=true;}
function save(){if(readBlocked)return false;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageError='';return true;}catch{storageError='浏览器未能保存数据。当前修改仅在本次打开期间有效，请到设置导出备份。';toast('保存失败，请导出备份');return false;}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),3400);}
function paintIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
function prettyDate(date){return new Date(date+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'});}
function dateName(date){const today=dateKey();return date===today?'今天':date===shiftDate(today,1)?'明天':date===shiftDate(today,-1)?'昨天':new Date(date+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric'});}
function timeText(n){if(n<60)return `${n} 分钟`;const h=Math.floor(n/60),m=n%60;return `${h} 小时${m?` ${m} 分钟`:''}`;}
function demoBanner(){return state.demo?`<div class="demo-bar"><span><strong>先用示例感受一下</strong> · 当前空间包含示例安排与记忆。</span><button data-action="clear-demo">清空示例，开始使用 ${icon('arrow-right')}</button></div>`:'';}
function pageHead(title,sub,action=''){return `<div class="page-head"><div><span class="eyebrow">A LITTLE MORE INTENTIONAL</span><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function dateControls(){return `<div class="date-controls"><button class="icon-button" data-action="prev-date" aria-label="前一天">${icon('chevron-left')}</button><input type="date" id="selected-date" value="${state.selectedDate}" aria-label="查看日期"><button class="icon-button" data-action="next-date" aria-label="后一天">${icon('chevron-right')}</button></div>`;}
function render(){
 document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
 $('#breadcrumb').textContent={today:'今日安排',memory:'记忆空间',roles:'生活角色',settings:'偏好设置'}[view];
 $('#nav-count').textContent=state.tasks.filter(t=>t.date===state.selectedDate&&!t.done).length;
 $('#main').innerHTML=(storageError?`<div class="storage-alert" role="alert">${esc(storageError)}</div>`:'')+({today:renderToday,memory:renderMemory,roles:renderRoles,settings:renderSettings}[view])();paintIcons();tick();
}
function focusCard(plan){
 const active=state.focus&&state.tasks.find(t=>t.id===state.focus.taskId);const next=active||nextTask(plan,state.selectedDate);
 if(!next)return `<section class="focus-card"><div class="focus-top">${icon('sparkles')} 下一步，留一点空白<span class="focus-badge">自己的节奏</span></div><div class="focus-body"><div class="focus-content"><h2>${state.tasks.some(t=>t.date===state.selectedDate)?'已经做了不少，歇一会儿吧。':'从一件重要的小事开始。'}</h2><p>不用把每一分钟都填满。留出时间，也是一种安排。</p><button class="button white" data-action="add-task">${icon('plus')} 添加一个安排</button></div><div class="focus-clock">${icon('sun')}<span>留白时间</span></div></div></section>`;
 const planned=plan.scheduled.find(t=>t.id===next.id);const duration=active?state.focus.initialSeconds/60:Math.min(next.duration,state.prefs.focusMinutes);
 const explain=next.notes||(planned?.fixed?'这是你预留的固定时间。':next.priority===3?'这件事被你标为优先处理，先为它留一段完整时间。':'根据可用时间与角色优先级，为这件事留出一个位置。');
 return `<section class="focus-card" id="focus-card"><div class="focus-top">${icon('sparkles')} ${active?'专注进行中':'下一步建议'}<span class="focus-badge">${active?'跟随你的节奏':dateName(state.selectedDate)+' · '+(planned?clock(planned.start):'待安排')}</span></div><div class="focus-body"><div class="focus-content"><h2>${esc(next.title)}</h2><p>${esc(explain)}</p><div class="focus-actions">${active?`<button class="button white" data-action="toggle-focus" id="focus-toggle">${icon(state.focus.paused?'play':'pause')} ${state.focus.paused?'继续专注':'暂停一下'}</button><button class="subtle" data-action="complete" data-id="${esc(next.id)}">${icon('check')} 已完成</button><button class="subtle" data-action="stop-focus" aria-label="结束计时">${icon('stop')}</button>`:`<button class="button white" data-action="start-focus" data-id="${esc(next.id)}">${icon('play')} 开始专注</button><button class="subtle" data-action="tomorrow" data-id="${esc(next.id)}">稍后再做 ${icon('chevrons')}</button>`}</div></div><div class="focus-clock"><strong id="focus-time">${String(duration).padStart(2,'0')}:00</strong><span id="focus-caption">${active?'剩余时间':'分钟 · 专注一件事'}</span></div></div></section>`;
}
function taskRow(task,next){return `<div class="task-row ${task.done?'is-done':''}"><div class="time-label">${task.done&&!task.time?'已完成':clock(task.start)}<small>${task.done&&!task.time?'':clock(task.end)}</small></div><span class="timeline-dot" style="color:${roleOf(task.role).color}"></span><div class="task-content ${next?.id===task.id&&!task.done?'current':''}"><button class="task-title-button" data-action="edit-task" data-id="${esc(task.id)}">${esc(task.title)}</button><div class="task-meta">${tag(task.role)}<span class="task-duration">${icon('clock')} ${task.duration} 分钟</span><span class="task-status ${task.conflict||task.outside?'warning':''}">${task.done?'已完成':task.conflict?'时间有重叠':task.outside?'超出可安排时段':task.fixed?'固定时间':'灵活安排'}</span></div></div><button class="task-complete ${task.done?'done':''}" data-action="complete" data-id="${esc(task.id)}" aria-label="${task.done?'恢复任务':'标记完成'}：${esc(task.title)}">${task.done?icon('check'):''}</button></div>`;}
function renderToday(){
 const date=state.selectedDate,day=state.tasks.filter(t=>t.date===date),plan=planDay(state.tasks,state.prefs,date),next=nextTask(plan,date),done=day.filter(t=>t.done).length,total=day.reduce((n,t)=>n+t.duration,0),activeRoles=new Set(day.map(t=>t.role)).size;
 const rows=plan.scheduled.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done));
 const overdue=state.tasks.filter(t=>!t.done&&t.date<dateKey()&&t.date!==date);
 return pageHead(`${dateName(date)}，按自己的节奏。`,`${prettyDate(date)} · 每个角色，都值得被照顾。`,`<div class="head-actions">${dateControls()}<button class="button primary" data-action="add-task">${icon('plus')} 添加安排</button></div>`)+demoBanner()+
 (overdue.length?`<div class="warning-inline">${icon('info')} 有 ${overdue.length} 件过去的安排尚未完成。<button data-action="carry-over">移到当前日期</button></div>`:'')+
 `<div class="dashboard"><div class="main-column">${focusCard(plan)}<div class="stat-grid"><div class="stat"><span class="stat-icon">${icon('clock')}</span><div><strong>${Math.floor(total/60)}<small>小时${total%60?' '+total%60+' 分':''}</small></strong><p>计划投入的时间</p></div></div><div class="stat"><span class="stat-icon">${icon('check-circle')}</span><div><strong>${done}<small>/ ${day.length} 件</small></strong><p>已经完成的安排</p></div></div><div class="stat"><span class="stat-icon">${icon('circles')}</span><div><strong>${activeRoles}<small>/ 4 个</small></strong><p>今天照顾的角色</p></div></div></div><section class="panel schedule-panel"><div class="panel-heading"><h2>时间安排 <span>${day.length} 件事</span></h2><div class="schedule-tabs" aria-label="任务状态筛选">${[['all','全部'],['todo','待办'],['done','完成']].map(([id,label])=>`<button class="${taskFilter===id?'active':''}" data-action="task-filter" data-filter="${id}" aria-pressed="${taskFilter===id}">${label}</button>`).join('')}</div></div><div class="schedule-list">${rows.map(t=>taskRow(t,next)).join('')||`<div class="empty-state">${icon('calendar')}<h3>${taskFilter==='done'?'每一小步都算数':'这里还有可以留给自己的时间'}</h3><p>${taskFilter==='done'?'完成一件事后，点右侧的圆圈，把这一小步留下来。':'添加一个安排，选择时长和角色，时间线会为它找到位置。'}</p></div>`}</div>${plan.overflow.length?`<div class="overflow-box"><strong>时间不够，先不勉强安排</strong>${plan.overflow.map(t=>`<div class="overflow-task"><span>${esc(t.title)} · ${t.duration} 分钟</span><button data-action="tomorrow" data-id="${esc(t.id)}">移到明天</button></div>`).join('')}</div>`:''}<button class="add-row" data-action="add-task">${icon('plus')} 再为一件事留出时间</button></section></div><aside class="right-column"><section class="panel"><div class="panel-heading"><h2>生活不止一面</h2><button class="icon-button" data-action="go-roles" aria-label="管理生活角色">${icon('arrow-right')}</button></div><p class="balance-subtitle">看看时间，留给了哪些重要的部分。</p>${roles.map(r=>{const n=day.filter(t=>t.role===r.id).reduce((s,t)=>s+t.duration,0);return `<div class="role-row">${roleIcon(r)}<div class="role-progress"><div class="role-label"><span>${r.name}</span><span>${n?timeText(n):'留一点空间'}</span></div><div class="progress-track"><div class="progress-fill" style="--role-color:${r.color};width:${total?n/total*100:0}%"></div></div></div></div>`;}).join('')}<div class="balance-note">${icon('info')} 时间比例没有标准答案，以你在意的事为准。</div></section><section class="panel"><div class="panel-heading"><h2>最近记住的事</h2><button class="text-link" data-action="go-memory">全部</button></div>${state.memories.slice(-2).reverse().map(m=>`<article class="mini-memory"><button data-action="edit-memory" data-id="${esc(m.id)}">${esc(m.title)}</button><p>${esc(m.content)}</p><div class="mini-date">${icon('book')} ${esc(m.source||'我的记录')} · ${types[m.type]}</div></article>`).join('')||`<p class="subheading">记下一个偏好，或下一次想接着做的事。</p><button class="button secondary small" data-action="add-memory">${icon('plus')} 添加记忆</button>`}</section><div class="gentle-card">${icon('moon')}<div><strong>今天也给自己留一点余地</strong><p>没有完成的事，可以重新安排。<br>你的生活，不需要被填满。</p></div></div></aside></div>`;
}
function renderMemory(){
 const list=state.memories.filter(m=>memoryFilter==='all'||m.type===memoryFilter).slice().reverse();
 return pageHead('重要的事，慢慢记住。',`${state.memories.length} 条记忆 · 你可以随时查看、纠正或删除。`,`<div class="head-actions"><button class="button primary" data-action="add-memory">${icon('plus')} 添加记忆</button></div>`)+demoBanner()+`<div class="filter-bar">${[['all','全部记忆'],...Object.entries(types)].map(([id,label])=>`<button class="filter-chip ${memoryFilter===id?'active':''}" data-action="memory-filter" data-filter="${id}" aria-pressed="${memoryFilter===id}">${label}</button>`).join('')}</div><div class="memory-grid">${list.map(m=>`<article class="memory-card"><div class="memory-card-top"><span class="memory-type">${icon(m.type==='insight'?'sparkles':m.type==='preference'?'heart':'book')} ${types[m.type]}</span><button class="icon-button" data-action="edit-memory" data-id="${esc(m.id)}" aria-label="编辑记忆：${esc(m.title)}">${icon('edit')}</button></div><h3>${esc(m.title)}</h3><p>${esc(m.content)}</p><div class="memory-card-bottom"><span>来源：${esc(m.source||'我的记录')}</span>${tag(m.role)}</div></article>`).join('')}</div>${!list.length?`<section class="panel"><div class="empty-state">${icon('layers')}<h3>先留下一件值得记住的事</h3><p>一个偏好，一段进展，或给未来自己的提示。你决定什么值得留下。</p><button class="button primary" data-action="add-memory">${icon('plus')} 添加记忆</button></div></section>`:''}`;
}
function renderRoles(){
 return pageHead('每一面，都是你。','为不同的角色留出时间，也允许自己的重心变化。')+`<div class="roles-grid">${roles.map(r=>{const tasks=state.tasks.filter(t=>t.role===r.id&&t.date===state.selectedDate),n=tasks.reduce((s,t)=>s+t.duration,0);return `<section class="role-card"><div class="role-card-head">${roleIcon(r)}<div><h2>${r.name}</h2><p>${{work:'创造、学习，以及想推进的事情',family:'伴侣、家人、朋友，与彼此的时间',health:'运动、休息，以及照顾身体',self:'兴趣、仪容，以及让自己开心的小事'}[r.id]}</p></div></div><div class="role-metrics"><div><strong>${tasks.length}</strong><span>当前日期的安排</span></div><div><strong>${n}<small style="font-size:13px;color:#9aa5b8"> 分钟</small></strong><span>${dateName(state.selectedDate)}的投入</span></div></div><label><div class="range-label">安排时的优先程度 <span id="weight-label-${r.id}">${state.prefs.weights[r.id]} / 5</span></div><input type="range" min="1" max="5" step="1" value="${state.prefs.weights[r.id]}" data-role-weight="${r.id}" aria-label="${r.name}优先程度"></label><button class="button secondary small" data-action="add-role-task" data-role="${r.id}">${icon('plus')} 为这一面安排时间</button></section>`;}).join('')}</div><p class="subheading">同等重要程度的灵活任务，会优先为你更在意的角色安排时间。固定约定保持不变。</p>`;
}
function renderSettings(){return pageHead('舒服的节奏，由你决定。','先设置边界，让安排适应你的生活。')+`<div class="settings-layout"><section class="panel"><h2>我的一天</h2><form id="settings-form"><div class="form-grid"><label>从几点开始安排<input type="time" name="start" value="${state.prefs.start}" required></label><label>几点之后留给自己<input type="time" name="end" value="${state.prefs.end}" required></label></div><label>通常什么时候更适合专注<select name="peak"><option value="morning" ${state.prefs.peak==='morning'?'selected':''}>上午 · 从重要的事开始</option><option value="afternoon" ${state.prefs.peak==='afternoon'?'selected':''}>下午 · 慢慢进入状态</option><option value="evening" ${state.prefs.peak==='evening'?'selected':''}>晚上 · 安静一点的时间</option></select></label><label>一次专注多长时间（分钟）<input type="number" name="focusMinutes" min="5" max="120" step="1" value="${state.prefs.focusMinutes}" required></label><p class="form-error" id="settings-error" role="alert"></p><button class="button primary" type="submit">保存我的节奏 ${icon('check')}</button></form><div class="settings-section"><h2>数据与备份</h2><p>记录只保存在当前浏览器，不会同步到其他设备。清理网站数据会删除记录；换设备前可以导出备份。备份是普通 JSON 文件，请妥善保管。</p><div class="settings-buttons"><button class="button secondary" data-action="export">${icon('download')} 导出备份</button><button class="button secondary" data-action="import">${icon('upload')} 恢复备份</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><div class="settings-buttons" style="margin-top:14px"><button class="button ghost danger-text" data-action="clear-all">清空当前浏览器数据</button><button class="button ghost" data-action="load-demo">载入示例</button></div></div></section><aside><section class="panel"><h2>你掌握自己的记录</h2><ul class="privacy-list"><li>${icon('shield')}<span>任务与记忆保存在浏览器。使用同一设备的人可能访问到这些记录，请使用自己的浏览器账户。</span></li><li>${icon('layers')}<span>记忆由你添加和编辑，保留信息来源。当前没有在后台采集你的电脑内容。</span></li><li>${icon('calendar')}<span>下一步建议根据任务重要程度、角色优先级和可用时间生成。当前版本尚未连接大模型。</span></li></ul><div class="settings-section"><h2>当前连接</h2><div class="status-row"><span>浏览器本地存储</span><span class="status-pill">${storageError?'保存异常':'已启用'}</span></div><div class="status-row"><span>电脑活动记录</span><span class="status-pill neutral">未接入</span></div><div class="status-row"><span>日历与手表</span><span class="status-pill neutral">未接入</span></div><p>专注计时需要页面保持打开或恢复打开。当前版本不在页面关闭后发送通知。</p></div></section></aside></div>`;}

function go(to){view=to;location.hash=to;render();window.scrollTo({top:0});}
function openTask(id=null,role=null){
 const t=state.tasks.find(t=>t.id===id),form=$('#task-form');form.reset();form.elements.id.value=t?.id||'';form.elements.title.value=t?.title||'';form.elements.role.value=t?.role||role||'work';form.elements.duration.value=t?.duration||30;form.elements.priority.value=t?.priority||2;form.elements.date.value=t?.date||state.selectedDate;form.elements.time.value=t?.time||'';form.elements.notes.value=t?.notes||'';$('#fixed-time-toggle').checked=!!t?.time;$('#fixed-time-field').hidden=!t?.time;$('#task-error').textContent='';$('#task-delete').hidden=!t;$('#task-dialog-title').textContent=t?'调整这段时间':'留出一段时间';$('#task-dialog').showModal();form.elements.title.focus();
}
function openMemory(id=null){const m=state.memories.find(m=>m.id===id),f=$('#memory-form');f.reset();for(const name of ['id','title','content','type','role','source'])f.elements[name].value=m?.[name]??({type:'fact',role:'work',source:'我的记录'}[name]||'');$('#memory-delete').hidden=!m;$('#memory-dialog-title').textContent=m?'重新整理这条记忆':'记住这件事';$('#memory-error').textContent='';$('#memory-dialog').showModal();f.elements.title.focus();}
function ask(title,message,yes='确认'){return new Promise(resolve=>{const d=$('#confirm-dialog');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;$('#confirm-yes').textContent=yes;const end=v=>{d.close();resolve(v);};$('#confirm-yes').onclick=()=>end(true);$('#confirm-cancel').onclick=()=>end(false);d.oncancel=()=>resolve(false);d.showModal();$('#confirm-cancel').focus();});}
function complete(id){const t=state.tasks.find(t=>t.id===id);if(!t)return;t.done=!t.done;t.doneAt=t.done?new Date().toISOString():null;if(state.focus?.taskId===id)state.focus=null;const ok=save();render();toast(ok?(t.done?'这一小步，已经完成。':'已恢复为待办'):'修改未保存，请导出备份');}
async function startFocus(id){const t=state.tasks.find(t=>t.id===id);if(!t||t.done)return;if(state.focus&&state.focus.taskId!==id&&!await ask('切换专注任务？','当前计时会结束，原任务仍保留为待办。','切换'))return;const seconds=Math.min(t.duration,state.prefs.focusMinutes)*60;state.focus={taskId:id,endAt:Date.now()+seconds*1000,remaining:seconds,initialSeconds:seconds,paused:false};save();render();toast('这段时间，专心做一件事。');}
function tick(){if(!state.focus)return;const f=state.focus,remaining=f.paused?f.remaining:Math.max(0,Math.ceil((f.endAt-Date.now())/1000));const label=$('#focus-time');if(label)label.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if($('#focus-caption'))$('#focus-caption').textContent=remaining===0?'时间到了，记得休息':f.paused?'已经暂停':'剩余时间';if($('#focus-card'))$('#focus-card').classList.toggle('finished',remaining===0);if($('#focus-toggle'))$('#focus-toggle').disabled=remaining===0;}
function toggleFocus(){if(!state.focus)return;const f=state.focus;if(f.paused){f.endAt=Date.now()+f.remaining*1000;f.paused=false;}else{f.remaining=Math.max(0,Math.ceil((f.endAt-Date.now())/1000));f.paused=true;}save();render();}
function searchResults(q){q=q.trim().toLowerCase();const list=[...state.tasks.map(t=>({...t,kind:'task',text:t.title+' '+t.notes})),...state.memories.map(m=>({...m,kind:'memory',text:m.title+' '+m.content+' '+m.source}))].filter(x=>q&&x.text.toLowerCase().includes(q)).slice(0,30);$('#search-results').innerHTML=!q?'<p>搜索一件事，或一个记住的想法。</p>':!list.length?'<p>没有找到相关记录，换个词试试。</p>':list.map(x=>`<button class="search-result" data-action="search-result" data-kind="${x.kind}" data-id="${esc(x.id)}">${icon(x.kind==='task'?'calendar':'layers')}<div><strong>${esc(x.title)}</strong><small>${x.kind==='task'?`${esc(x.date)} · ${x.done?'已完成':'待办'}`:types[x.type]}</small></div></button>`).join('');}
function openSearch(){$('#search-dialog').showModal();$('#global-search').value='';searchResults('');$('#global-search').focus();}
async function clearAll(demoOnly=false){if(!await ask(demoOnly?'开始记录自己的生活？':'清空当前浏览器的数据？',demoOnly?'示例和在示例中所做的修改都会移除；保留你的节奏偏好。':'任务、记忆和计时都会移除，无法撤销。建议先导出备份。',demoOnly?'清空示例':'清空数据'))return;const prefs=state.prefs;state=emptyState();if(demoOnly)state.prefs=prefs;readBlocked=false;save();render();toast('新的空间，留给你自己的生活。');}
async function importBackup(file){try{if(!file)return;if(file.size>5*1024*1024)throw Error('备份文件需小于 5 MB');const parsed=sanitizeState(JSON.parse(await file.text()));if(!await ask('用备份替换当前记录？',`将恢复 ${parsed.tasks.length} 个任务和 ${parsed.memories.length} 条记忆。当前记录会被替换。`,'恢复'))return;state=parsed;state.focus=null;readBlocked=false;const ok=save();render();toast(ok?'备份已恢复':'恢复的数据尚未保存，请保留备份');}catch(e){toast('无法恢复：'+e.message);}}
function exportBackup(){const raw=readBlocked?localStorage.getItem(STORAGE_KEY):JSON.stringify({...state,focus:null},null,2);const blob=new Blob([raw||''],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`myself-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已准备，请妥善保管。');}

document.addEventListener('click',async e=>{
 const nav=e.target.closest('[data-view]');if(nav){go(nav.dataset.view);return;}
 const close=e.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}
 const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;
 switch(action){
 case 'add-task':openTask();break;case 'edit-task':openTask(id);break;case 'add-role-task':openTask(null,el.dataset.role);break;
 case 'add-memory':openMemory();break;case 'edit-memory':openMemory(id);break;
 case 'prev-date':case 'next-date':state.selectedDate=shiftDate(state.selectedDate,action==='prev-date'?-1:1);save();render();break;
 case 'task-filter':taskFilter=el.dataset.filter;render();break;case 'memory-filter':memoryFilter=el.dataset.filter;render();break;
 case 'go-roles':go('roles');break;case 'go-memory':go('memory');break;
 case 'complete':complete(id);break;case 'start-focus':await startFocus(id);break;case 'toggle-focus':toggleFocus();break;
 case 'stop-focus':state.focus=null;save();render();toast('计时已结束，任务仍保留。');break;
 case 'tomorrow':{const t=state.tasks.find(t=>t.id===id);if(!t)break;t.date=shiftDate(t.date<dateKey()?dateKey():t.date,1);if(state.focus?.taskId===id)state.focus=null;const ok=save();render();toast(ok?`已移到 ${prettyDate(t.date)}`:'修改未保存，请导出备份');break;}
 case 'carry-over':state.tasks.forEach(t=>{if(!t.done&&t.date<dateKey()&&t.date!==state.selectedDate)t.date=state.selectedDate;});save();render();toast('已移入当前日期，固定时间冲突会单独标出。');break;
 case 'clear-demo':await clearAll(true);break;case 'clear-all':await clearAll();break;
 case 'load-demo':if(await ask('载入示例内容？','当前任务与记忆会被示例替换，建议先导出备份。','载入')){state=defaultState();readBlocked=false;save();render();toast('已载入示例。');}break;
 case 'export':exportBackup();break;case 'import':$('#import-file').click();break;
 case 'search-result':$('#search-dialog').close();el.dataset.kind==='task'?openTask(id):openMemory(id);break;
 }
});
document.addEventListener('change',e=>{
 if(e.target.id==='selected-date'&&e.target.value){state.selectedDate=e.target.value;save();render();}
 if(e.target.dataset.roleWeight){const role=e.target.dataset.roleWeight;state.prefs.weights[role]=Number(e.target.value);const ok=save();$('#weight-label-'+role).textContent=`${e.target.value} / 5`;if(ok)toast('角色优先程度已更新。');}
 if(e.target.id==='import-file')importBackup(e.target.files[0]);
});
document.addEventListener('input',e=>{if(e.target.dataset.roleWeight)$('#weight-label-'+e.target.dataset.roleWeight).textContent=`${e.target.value} / 5`;});
$('#fixed-time-toggle').addEventListener('change',e=>{$('#fixed-time-field').hidden=!e.target.checked;});
$('#task-form').addEventListener('submit',e=>{e.preventDefault();try{const d=new FormData(e.target),input={id:d.get('id'),title:d.get('title'),role:d.get('role'),date:d.get('date'),time:$('#fixed-time-toggle').checked?d.get('time'):'',duration:Number(d.get('duration')),priority:Number(d.get('priority')),notes:d.get('notes')};if($('#fixed-time-toggle').checked&&!input.time)throw Error('请选择固定开始时间');state=applyTask(state,input);state.selectedDate=input.date;const ok=save();$('#task-dialog').close();render();toast(ok?'安排已保存，时间线已更新。':'修改未保存，请导出备份');}catch(err){$('#task-error').textContent=err.message;}});
$('#task-delete').addEventListener('click',async()=>{const id=$('#task-form').elements.id.value;if(await ask('删除这个安排？','这项任务会从时间线中移除。','删除')){state.tasks=state.tasks.filter(t=>t.id!==id);if(state.focus?.taskId===id)state.focus=null;const ok=save();$('#task-dialog').close();render();toast(ok?'任务已删除。':'修改未保存，请导出备份');}});
$('#memory-form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),title=String(d.get('title')).trim(),content=String(d.get('content')).trim();if(!title||!content){$('#memory-error').textContent='请填写标题和内容';return;}const id=d.get('id'),old=state.memories.find(m=>m.id===id),m={id:old?.id||uid(),title,content,type:d.get('type'),role:d.get('role'),source:String(d.get('source')).trim()||'我的记录',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};state.memories=old?state.memories.map(x=>x.id===id?m:x):[...state.memories,m];const ok=save();$('#memory-dialog').close();render();toast(ok?'已经记住了。':'修改未保存，请导出备份');});
$('#memory-delete').addEventListener('click',async()=>{const id=$('#memory-form').elements.id.value;if(await ask('删除这条记忆？','删除后不再显示在记忆空间中，无法撤销。','删除')){state.memories=state.memories.filter(m=>m.id!==id);const ok=save();$('#memory-dialog').close();render();toast(ok?'记忆已删除。':'修改未保存，请导出备份');}});
document.addEventListener('submit',e=>{if(e.target.id!=='settings-form')return;e.preventDefault();try{const d=new FormData(e.target);state.prefs=validatePrefs({...state.prefs,start:d.get('start'),end:d.get('end'),peak:d.get('peak'),focusMinutes:Number(d.get('focusMinutes'))});const ok=save();render();toast(ok?'你的节奏已保存。':'修改未保存，请导出备份');}catch(err){$('#settings-error').textContent=err.message;}});
$('#search-open').addEventListener('click',openSearch);$('#global-search').addEventListener('input',e=>searchResults(e.target.value));
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!document.querySelector('dialog[open]'))openSearch();}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
window.addEventListener('hashchange',()=>{const value=location.hash.slice(1);if(['today','memory','roles','settings'].includes(value)&&value!==view){view=value;render();}});
window.addEventListener('storage',e=>{if(e.key!==STORAGE_KEY)return;try{state=e.newValue?sanitizeState(JSON.parse(e.newValue)):emptyState();render();toast('已同步另一个标签页的修改。');}catch{toast('另一个标签页的数据无法读取，请导出备份。');}});
for(const id of ['task-role','memory-role'])$('#'+id).innerHTML=roles.map(r=>`<option value="${r.id}">${r.name}</option>`).join('');
render();if(!readBlocked)save();setInterval(tick,1000);

if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tools=[{name:'myself_read_day',title:'查看一天的安排',description:'读取指定日期的任务安排，不修改任何数据。',inputSchema:{type:'object',properties:{date:{type:'string',format:'date'}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||!isDate(input.date))throw Error('date must be YYYY-MM-DD');const plan=planDay(state.tasks,state.prefs,input.date);return {date:input.date,tasks:plan.scheduled.map(t=>({id:t.id,title:t.title,start:clock(t.start),duration:t.duration,role:t.role,done:t.done})),unscheduled:plan.overflow.map(t=>({id:t.id,title:t.title}))};}},
 {name:'myself_start_task_form',title:'准备一个新安排',description:'打开任务表单并预填标题；只有用户点击保存才会创建任务。',inputSchema:{type:'object',properties:{title:{type:'string',minLength:1,maxLength:160}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(typeof input?.title!=='string'||!input.title.trim()||input.title.length>160)throw Error('title must contain 1–160 characters');if(document.querySelector('dialog[open]'))throw Error('请先完成或关闭当前弹窗');openTask();$('#task-form').elements.title.value=input.title;return {status:'form_open',saved:false};}}];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
